/**
 * N8N Channel Mapper - Copy & Paste Ready
 *
 * N8N Code 노드에 그대로 복붙하세요
 *
 * 지원 기능:
 * - Google VEO 3.1 (First+Last Frame interpolation)
 * - BGM (archive.org URL, seekStart 지원)
 * - Sound Effects (Freesound API 프리셋)
 * - 이중 자막 (textEnglish 필드 있으면 자동 생성)
 * - YouTube 자동 업로드
 */

// ============================================
// 📥 Input 받기
// ============================================
const input = $input.first().json;
const channelType = input.channel_type || "why_cat";

console.log(`선택된 채널 타입: ${channelType}`);

// ============================================
// 🎬 채널별 설정
// ============================================
const channelSettings = {
  // ============================================
  // 🐱 WHY_CAT (InkMilk) - 영어권 고양이 채널
  // ============================================
  "why_cat": {
    name: "why_cat",
    displayName: "InkMilk",
    description: "Cat couple comedy shorts (English)",
    language: "english",

    profileId: "cat-couple",
    characterIds: ["kami", "dalgi"],
    characterDescriptions: {
      "kami": "Black cat wearing light blue t-shirt, round brown eyes, playful personality",
      "dalgi": "White cat wearing pink strawberry pattern dress with pink bow on right ear, cute and mischievous"
    },

    style: "cute",
    veo3Priority: true,

    audio: {
      skipTTS: true,
      voice: null,
      bgm: {
        source: "https://archive.org/download/10.-la-violette-africaine/03.%20Les%20Champs-Elysees.mp3",
        volume: 0.25,
        loop: true,
        seekStart: 2
      },
      sfxPresets: ["CAT_MEOW", "CAT_PURR", "WHOOSH", "POP", "SUCCESS", "MAGIC"],
      sfxVolume: 0.3
    },

    video: {
      orientation: "portrait",
      generateVideos: true,
      useFrameInterpolation: true,
      useSceneTransitions: true,
      sceneTransitionType: "fade",
      sceneTransitionDuration: 0.3,
      useStoredImageForVeo: true
    },

    titleText: {
      style: "highlight",
      position: "top",
      duration: "full"
    },

    youtube: {
      enabled: true,
      channelName: "why_cat",
      subChannel: "inkmilk",
      defaultPrivacy: "unlisted",
      defaultTags: ["cat", "shorts", "funny", "cute", "kami", "dalgi", "InkMilk"],
      hashtagTemplate: "#shorts #cat #funny #cute"
    }
  },

  // ============================================
  // 🎯 CLICKAROUND - 메인 채널 (한국어)
  // ============================================
  "clickaround": {
    name: "clickaround",
    displayName: "클릭어라운드",
    description: "메인 채널 - 다양한 콘텐츠",
    language: "korean",

    profileId: null,
    characterIds: [],
    characterDescriptions: {},

    style: "general",
    veo3Priority: false,

    audio: {
      skipTTS: false,
      voice: "pNInz6obpgDQGcFmaJgB",
      bgm: {
        source: "https://archive.org/download/10.-la-violette-africaine/03.%20Les%20Champs-Elysees.mp3",
        volume: 0.15,
        loop: true,
        seekStart: 0
      },
      sfxPresets: [],
      sfxVolume: 0.3
    },

    video: {
      orientation: "portrait",
      generateVideos: true,
      useFrameInterpolation: true,
      useSceneTransitions: true,
      sceneTransitionType: "fade",
      sceneTransitionDuration: 0.3,
      useStoredImageForVeo: false
    },

    titleText: {
      style: "highlight",
      position: "top",
      duration: "full"
    },

    youtube: {
      enabled: true,
      channelName: "clickaround",
      defaultPrivacy: "unlisted",
      defaultTags: ["shorts"],
      hashtagTemplate: "#shorts"
    }
  }
};

// ============================================
// 🎵 SFX 프리셋 목록 (참고용)
// ============================================
const SFX_PRESETS = {
  CAT_MEOW: "cat meow cute",
  CAT_PURR: "cat purring relaxed",
  CAT_HISS: "cat hissing angry",
  WHOOSH: "whoosh transition fast",
  POP: "pop bubble cartoon",
  MAGIC: "magic sparkle fairy",
  SUCCESS: "success achievement ding",
  FAIL: "fail buzzer wrong",
  LAUGH: "cartoon laugh funny",
  GASP: "surprised gasp",
  AWW: "cute aww sound",
  DOOR: "door opening creak",
  FOOTSTEPS: "footsteps walking",
  CLOCK: "clock ticking"
};

// ============================================
// 📤 Output
// ============================================
const selectedChannel = channelSettings[channelType];

if (!selectedChannel) {
  throw new Error(`Unknown channel type: ${channelType}`);
}

return [{
  json: {
    channel_type: channelType,
    channel_config: selectedChannel,
    target_language: selectedChannel.language,
    voice_preference: selectedChannel.audio.voice,
    content_style: selectedChannel.style,
    channel_name: selectedChannel.name,
    veo3_priority: selectedChannel.veo3Priority,
    description: selectedChannel.description,
    profileId: selectedChannel.profileId,
    characterIds: selectedChannel.characterIds,
    characterDescriptions: selectedChannel.characterDescriptions,
    audio_config: selectedChannel.audio,
    video_config: selectedChannel.video,
    titleText_config: selectedChannel.titleText,
    youtube_config: selectedChannel.youtube,
    sfx_presets: SFX_PRESETS,
    timestamp: new Date().toISOString()
  }
}];

/**
 * N8N Category Selector - WHY_CAT 전용
 *
 * 시리즈만 정의 → GPT가 에피소드 생성
 * 게스트 캐릭터: 등록된 캐릭터만 사용
 *
 * 이전 노드: Channel Mapper
 */

// ============================================
// 📥 Channel Mapper에서 설정 받기
// ============================================
const channelData = $('Channel Mapper').first().json;

// ============================================
// 📅 날짜 기반 순차 인덱스
// ============================================
function getDayOfYear() {
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = now - start;
  return Math.floor(diff / (1000 * 60 * 60 * 24));
}

const dayOfYear = getDayOfYear();

// ============================================
// �� 게스트 캐릭터 정의
// ============================================
// 등록 완료된 캐릭터만 true로 변경
const registeredGuests = {
  nabi: false,   // ���노바나나 ��미지 + API 등록 후 true로 변경
  momo: false,
  choco: false,
  boss: false
};

const guestCharacters = {
  nabi: {
    id: "nabi",
    name: "Nabi",
    description: "Orange tabby cat, neighbor, flirty and confident personality"
  },
  momo: {
    id: "momo",
    name: "Momo",
    description: "Tiny white kitten, innocent and curious, big round eyes"
  },
  choco: {
    id: "choco",
    name: "Choco",
    description: "Golden retriever puppy, friendly but clumsy"
  },
  boss: {
    id: "boss",
    name: "Boss",
    description: "Big grey cat, neighborhood alpha, intimidating presence"
  }
};

// ============================================
// 📺 시리즈 정의 (GPT가 에피소드 생성)
// ============================================
const allSeries = [
  {
    id: "daily_life",
    name: "Couple Daily Life",
    description: "Everyday moments of cat couple living together - morning routines, meals, naps, TV time, bedtime",
    themes: ["morning alarm", "coffee", "remote control", "blanket", "sunny spot", "snacks", "bathroom", "workout"],
    guests: [],
    mood: "funny, relatable, cute"
  },
  {
    id: "drama",
    name: "Dramatic Moments",
    description: "Relationship drama and misunderstandings between the couple",
    themes: ["jealousy", "phone notification", "lipstick mark", "anniversary", "silent treatment", "apology", "makeup"],
    guests: [],
    mood: "dramatic, funny, emotional"
  },
  {
    id: "nabi_arc",
    name: "Neighbor Nabi Arc",
    description: "Story arc with neighbor cat Nabi - jealousy, rivalry, eventually becoming friends",
    themes: ["new neighbor", "flirting", "confrontation", "misunderstanding", "friendship"],
    guests: ["nabi"],
    mood: "dramatic, jealous, resolution"
  },
  {
    id: "choco_arc",
    name: "Puppy Choco Arc",
    description: "A puppy joins the household - chaos, adjustment, protection, bonding",
    themes: ["dog arrives", "chaos", "training", "protection", "bonding"],
    guests: ["choco"],
    mood: "chaotic, funny, heartwarming"
  },
  {
    id: "momo_arc",
    name: "Baby Kitten Momo Arc",
    description: "Babysitting a tiny kitten - parenting chaos, teaching, emotional goodbye",
    themes: ["kitten arrives", "babysitting", "teaching", "goodbye"],
    guests: ["momo"],
    mood: "cute, chaotic, emotional"
  },
  {
    id: "parody",
    name: "Parody & Satire",
    description: "Cat versions of TV shows and situations - news, court, cooking show, interview, reality TV",
    themes: ["cat news", "cat court", "cooking show", "job interview", "reality TV", "fitness channel"],
    guests: [],
    mood: "funny, satirical, clever"
  },
  {
    id: "seasonal",
    name: "Seasonal Events",
    description: "Holiday and season-based episodes - Christmas, New Year, Valentine, summer, rain, snow, birthdays",
    themes: ["christmas", "new year", "valentine", "summer heat", "rainy day", "first snow", "birthday"],
    guests: [],
    mood: "festive, cozy, sweet"
  },
  {
    id: "mystery",
    name: "Mystery & Scary",
    description: "Spooky and mysterious moments - cucumber scare, vacuum monster, 3AM noises, ghost hunting",
    themes: ["cucumber scare", "vacuum monster", "strange noise", "ghost hunt", "shadows"],
    guests: [],
    mood: "spooky, funny, brave"
  },
  {
    id: "romance",
    name: "Romance Moments",
    description: "Sweet romantic memories - how they met, proposal, anniversary, love letters",
    themes: ["first meeting", "proposal", "anniversary dinner", "love letter", "memories"],
    guests: [],
    mood: "romantic, sweet, nostalgic"
  }
];

// ============================================
// 🎯 사용 가능한 시리즈만 필터링
// ============================================
// 게스트가 필요 ���거나, 필요한 게스트가 모두 등록된 시리즈만 선택
const availableSeries = allSeries.filter(s => {
  if (s.guests.length === 0) return true;
  return s.guests.every(guestId => registeredGuests[guestId] === true);
});

console.log('Available series: ' + availableSeries.length + '/' + allSeries.length);

// ============================================
// 🎯 순차 선택
// ============================================
const index = dayOfYear % availableSeries.length;
const selected = availableSeries[index];
const nextIndex = (index + 1) % availableSeries.length;

// 게스트 캐릭터 정보 조합
const selectedGuests = selected.guests.map(guestId => guestCharacters[guestId]).filter(Boolean);

console.log('Day ' + dayOfYear + ' → Series: ' + selected.name);

// ============================================
// 📤 Output
// ============================================
return [{
  json: {
    // 시리즈 정보 (GPT가 이걸 보고 에피소드 생성)
    series_id: selected.id,
    series_name: selected.name,
    series_description: selected.description,
    series_themes: selected.themes,
    series_mood: selected.mood,

    // 캐릭터 정보
    main_characters: ["kami", "dalgi"],
    guest_characters: selectedGuests,
    registered_guests: registeredGuests,

    // 스케줄 ��보
    day_of_year: dayOfYear,
    series_index: index,
    total_series: allSeries.length,
    available_series: availableSeries.length,
    next_series: availableSeries[nextIndex].name,

    // Channel Mapper 설정 전달

    channel_type: $input.first().json.channel_type,
    channel_config: $input.first().json.channel_config,
    target_language: $input.first().json.target_language,
    voice_preference: $input.first().json.voice_preference,
    content_style: $input.first().json.content_style,
    channel_name : $input.first().json.channel_name,
    veo3_priority : $input.first().json.veo3_priority,
    profileId: $input.first().json.profileId,
    characterIds: $input.first().json.characterIds,
    characterDescriptions: $input.first().json.characterDescriptions,
    audio_config: $input.first().json.audio_config,
    video_config: $input.first().json.video_config,
    titleText_config: $input.first().json.titleText_config,
    youtube_config: $input.first().json.youtube_config,
    sfx_presets: $input.first().json.sfx_presets,
    timestamp: $input.first().json.timestamp,
  }
}];

// n8n Code Node: 그냥 2개 합치기
const gptRaw = $('InkMilk').item.json;
const gptOutput = gptRaw.output || gptRaw;
const config = $('category-selector').item.json;

// 그대로 합치기
const merged = {
  ...config,
  ...gptOutput
};

return { json: merged };

// n8n Code Node: Merged Data → API Request 변환
//
// Input: Merge/Extract 노드 결과 (Config + GPT/CatProject 합친 것)
// Output: consistent-shorts API 포맷 (COFFEE-BATTLE-7SFX.json 형식)
//
// ⭐ UPDATE: callback_url + hfbpo 메타데이터 추가 (Analytics 자동화용)

const merged = $input.item.json;

// CatProject 메타데이터 (Extract CatProject Body에서 전달)
const catprojectMeta = merged._catproject || {};

// API 포맷으로 변환
const apiRequest = {
  // 1. Character Reference
  characterReference: {
    profileId: merged.profileId,
    characterIds: merged.characterIds
  },

  // 2. Title Text (GPT + Config 스타일 병합)
  titleText: {
    ko: merged.titleText.ko,
    en: merged.titleText.en,
    style: merged.titleText_config?.style || "highlight",
    position: merged.titleText_config?.position || "top",
    duration: merged.titleText_config?.duration || "full"
  },

  // 3. Scenes (그대로)
  scenes: merged.scenes,

  // 4. Config (video_config + skipTTS)
  config: {
    orientation: merged.video_config.orientation,
    generateVideos: merged.video_config.generateVideos,
    useFrameInterpolation: merged.video_config.useFrameInterpolation,
    useSceneTransitions: merged.video_config.useSceneTransitions,
    sceneTransitionType: merged.video_config.sceneTransitionType,
    sceneTransitionDuration: merged.video_config.sceneTransitionDuration,
    skipTTS: merged.audio_config.skipTTS,
    useStoredImageForVeo: merged.video_config.useStoredImageForVeo,
    language: merged.target_language || merged.channel_config?.language || 'english'
  },

  // 5. Audio Config (⚠️ 키 이름 변경!)
  //    - bgm → backgroundMusic
  //    - soundEffects: 루트에서 여기로 이동
  audio_config: {
    backgroundMusic: {
      source: merged.audio_config.bgm.source,
      volume: merged.audio_config.bgm.volume,
      loop: merged.audio_config.bgm.loop,
      seekStart: merged.audio_config.bgm.seekStart || 0
    },
    soundEffects: merged.soundEffects || []
  },

  // 6. YouTube Upload (Config + GPT 병합)
  youtubeUpload: {
    enabled: merged.youtube_config?.enabled || false,
    channelName: merged.youtube_config?.channelName || merged.channel_name,
    subChannel: merged.youtube_config?.subChannel || null,
    title: merged.youtubeTitle,
    description: merged.youtubeDescription,
    tags: merged.youtube_config?.defaultTags || [],
    privacyStatus: merged.youtube_config?.defaultPrivacy || "unlisted"
  },

  // ⭐ 7. HFBPO/CatProject Integration (강화학습용)
  hfbpo: {
    combinationKey: catprojectMeta.combination_key || null,
    hookType: catprojectMeta.hook_type || null,
    conflictType: catprojectMeta.conflict_type || null,
    endingType: catprojectMeta.ending_type || null,
    trialNumber: catprojectMeta.trial_number || null,
    estimatedReward: catprojectMeta.estimated_reward || null
  },

  // ⭐ 8. Webhook Callback URL (Analytics 자동 수집용)
  // ShortVideoMaker가 YouTube 업로드 완료 후 이 URL로 콜백
  callback_url: "https://cgxr.app.n8n.cloud/webhook/catproject-upload-callback"
};

// hfbpo가 비어있으면 ���거 (InkMilk 경로 호환성)
if (!apiRequest.hfbpo.combinationKey) {
  delete apiRequest.hfbpo;
  delete apiRequest.callback_url;
}

console.log('[Transform] combination_key:', catprojectMeta.combination_key || 'N/A (InkMilk path)');

return { json: apiRequest };

// CatProject API → Transform 노드 형식 변환
const items = $input.all();
if (!items || items.length === 0) {
  throw new Error('No input from CatProject API');
}

const catResponse = items[0].json;
const combination = catResponse?.combination || {};
const episode = catResponse?.episode || {};
const apiBody = catResponse?.api_body || {};

// Transform 노드가 기대하는 형식으로 변환 (Merge 출력 형식)
const output = {
  // Character Reference (Transform이 기대하는 형식)
  profileId: apiBody.characterReference?.profileId || 'cat-couple',
  characterIds: apiBody.characterReference?.characterIds || ['kami', 'dalgi'],

  // Title Text
  titleText: apiBody.titleText || { ko: episode.title || '', en: '' },
  titleText_config: { style: 'highlight', position: 'top', duration: 'full' },

  // Scenes
  scenes: apiBody.scenes || [],

  // Video Config (Transform이 기대하는 형식)
  video_config: {
    orientation: apiBody.config?.orientation || 'portrait',
    generateVideos: apiBody.config?.generateVideos ?? true,
    useFrameInterpolation: apiBody.config?.useFrameInterpolation ?? true,
    useSceneTransitions: apiBody.config?.useSceneTransitions ?? true,
    sceneTransitionType: apiBody.config?.sceneTransitionType || 'xfade',
    sceneTransitionDuration: apiBody.config?.sceneTransitionDuration || 0.5,
    useStoredImageForVeo: apiBody.config?.useStoredImageForVeo ?? false
  },

  // Audio Config (Transform이 기대하는 형식)
  audio_config: {
    skipTTS: apiBody.audio_config?.skipTTS ?? false,
    bgm: {
      source: apiBody.audio_config?.backgroundMusic?.source || 'loudly',
      volume: apiBody.audio_config?.backgroundMusic?.volume || 0.15,
      loop: apiBody.audio_config?.backgroundMusic?.loop ?? true,
      seekStart: apiBody.audio_config?.backgroundMusic?.seekStart || 0
    }
  },

  // Sound Effects
  soundEffects: apiBody.audio_config?.soundEffects || [],

  // YouTube (Transform이 기��하는 형식)
  youtube_config: {
    enabled: apiBody.youtubeUpload?.enabled ?? true,
    channelName: apiBody.youtubeUpload?.channelName || 'why_cat',
    defaultTags: episode.hashtags || ['고양이', '커플', 'shorts'],
    defaultPrivacy: apiBody.youtubeUpload?.metadata?.privacyStatus || 'public'
  },
  channel_name: apiBody.youtubeUpload?.channelName || 'why_cat',
  youtubeTitle: apiBody.youtubeUpload?.metadata?.title || episode.youtubeTitle || episode.title || '',
  youtubeDescription: apiBody.youtubeUpload?.metadata?.description || episode.youtubeDescription || '',

  // Language
  target_language: apiBody.config?.language || 'korean',

  // CatProject 메타데이터 (reward 업데이트용)
  _catproject: {
    combination_key: combination.combination_key || 'unknown',
    hook_type: combination.hook_type,
    conflict_type: combination.conflict_type,
    ending_type: combination.ending_type,
    trial_number: combination.trial_number
  }
};

console.log('[CatProject] combination:', output._catproject.combination_key);
console.log('[CatProject] scenes:', output.scenes.length);

return [{ json: output }];

